import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Containerd + Kata","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosted/kata-containerd.md","filePath":"zh/self-hosted/kata-containerd.md","lastUpdated":1781609185000}'),n={name:"zh/self-hosted/kata-containerd.md"};function p(h,s,l,o,k,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="containerd-kata" tabindex="-1">Containerd + Kata <a class="header-anchor" href="#containerd-kata" aria-label="Permalink to &quot;Containerd + Kata&quot;">​</a></h1><p>Memoh 可以通过 <code>containerd</code> workspace backend 使用 Kata Containers 运行机器人 workspace。整体生命周期仍然走 Memoh 原来的 workspace 模型，但 containerd 会用 <code>io.containerd.kata.v2</code> 启动每个 workspace。</p><p>当你希望在 Linux/KVM 主机上获得 VM 级 workspace 隔离时，可以使用这个方案。macOS 和 Docker Desktop 主机不能运行这条路径。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>Memoh 部署在有 KVM 的 Linux 服务器上。</li><li>希望每个机器人 workspace 运行在轻量 VM 边界之后。</li><li>仍然希望 Memoh 的 workspace API、快照、文件、命令和界面控制保持和普通 <code>containerd</code> backend 一致。</li></ul><p>Memoh 目前仍通过 containerd snapshot 管理 Kata workspace。CPU 和内存限制是 hard limit。存储限制目前会保存并展示为 soft limit；等 VM 磁盘 quota 或 block-device quota 支持完成后，才能作为 hard limit 强制。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Linux 主机，并且存在 <code>/dev/kvm</code>。</li><li>如果主机本身也是 VM，需要开启 nested virtualization。</li><li>Docker 和 Docker Compose v2。</li><li>宿主机已安装 Kata Containers。</li><li>宿主机可用的 Kata runtime，例如 <code>io.containerd.kata.v2</code>。</li></ul><p>默认 compose overlay 会使用这些宿主机路径：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHIM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata/bin/containerd-shim-kata-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHARE_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/usr/share/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_OPT_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SYSLOG_SOCKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/run/systemd/journal/dev-log</span></span></code></pre></div><p>如果你的 Kata 安装路径不同，启动 Memoh 前先 export 对应变量。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>在 <code>config.toml</code> 里，workspace backend 仍然保持 <code>containerd</code>，同时设置 containerd runtime type：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">containerd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;io.containerd.kata.v2&quot;</span></span></code></pre></div><p><code>container_backend</code> 仍会显示为 <code>containerd</code>。要确认机器人 workspace 是否真的在用 Kata，需要看 workspace runtime：<code>runtime_backend = &quot;io.containerd.kata.v2&quot;</code>。</p><p>也可以在 Memoh server 的 containerd 环境里直接检查容器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> containers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bot-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>期望看到的 runtime name 是 <code>io.containerd.kata.v2</code>。</p><h2 id="compose-overlay" tabindex="-1">Compose overlay <a class="header-anchor" href="#compose-overlay" aria-label="Permalink to &quot;Compose overlay&quot;">​</a></h2><p>使用 Kata compose overlay 启动 Memoh：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.kata.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>这个 overlay 会把宿主机的 KVM 设备、Kata shim、Kata 配置和 Kata runtime assets 挂进 Memoh server 容器。</p><p>Dockerized Memoh server 会为机器人 workspace 运行一个嵌套 containerd。因此 Kata compose overlay 会给 server service 设置 <code>cgroup: host</code> 和 <code>shm_size: 1gb</code>。宿主机 cgroup namespace 允许嵌套 Kata runtime 创建 sandbox cgroup controllers；更大的 shared-memory segment 可以避免 Docker 默认 <code>/dev/shm</code> 太小导致的 QEMU/KVM 启动失败。</p><p>syslog socket 会挂载到 server 容器内的 <code>/dev/log</code>，让 Kata shim 可以初始化日志。在非 systemd 主机上，把 <code>MEMOH_KATA_SYSLOG_SOCKET</code> 设置为宿主机实际的 syslog socket 路径。</p><h2 id="bridge-网络" tabindex="-1">Bridge 网络 <a class="header-anchor" href="#bridge-网络" aria-label="Permalink to &quot;Bridge 网络&quot;">​</a></h2><p>Kata workspace 使用 bridge TCP listener（<code>BRIDGE_TCP_ADDR=:9090</code>），不使用普通 containerd workspace 的 Unix socket bridge。Unix socket 可能会通过 Kata shared filesystem 出现在宿主机上，但它不是一个可跨 guest VM 边界使用的连接端点。</p><p>Memoh 会把 Kata bridge 流量路由到 workspace 的 CNI IP。Bridge gRPC dial 也会绕过 HTTP proxy，避免 server 级别的 proxy 变量拦截私有 workspace 地址。</p><h2 id="build-proxy" tabindex="-1">Build proxy <a class="header-anchor" href="#build-proxy" aria-label="Permalink to &quot;Build proxy&quot;">​</a></h2><p>如果 Linux/KVM 主机在 Docker build 阶段需要代理，启动或重建 Kata compose stack 前设置 build proxy 变量：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_NO_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1,localhost</span></span></code></pre></div><p>这里要使用 Docker build 容器能访问到的宿主机地址。在 Linux 上，Dockerfile <code>RUN</code> 步骤里的 <code>localhost</code> 指的是 build 容器自己，不是宿主机。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>启动后，创建或重建一个机器人 workspace，并确认 workspace runtime 是 <code>io.containerd.kata.v2</code>。</p><p>也可以在 server 的 containerd 环境里直接跑一个 Kata runtime smoke test：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> io.containerd.kata.v2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --snapshotter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> overlayfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker.io/library/alpine:3.22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memoh-kata-smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /bin/sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;printf &quot;runtime-smoke-ok\\n&quot;&#39;</span></span></code></pre></div><p>如果直接 smoke test 通过，但机器人 workspace 无法启动，优先检查 server 日志里是否有 Kata shim、cgroup、<code>/dev/log</code>、<code>/dev/kvm</code> 或 bridge 连接错误。</p>`,36)])])}const g=a(n,[["render",p]]);export{c as __pageData,g as default};
